require "rails_helper"

# features/29_test_mapping. The test mapping is generated from the names of the tests and from
# the plans, read from their files: no test is run. The fixture repositories and their tests are
# built by spec/support/test_mapping_fixtures.rb, so no line of this file looks like a test.
RSpec.describe "TestMapping" do
  include_context "test mapping fixtures"

  # The first line of the mapping.
  def generated_line
    "Generated by `bin/rails test_mapping:write` from the test names and the plans. " \
      "Do not edit this file by hand: run `docker compose run --rm backend bin/rails test_mapping:write` " \
      "to write it again, and `docker compose run --rm backend bin/rails test_mapping:check` to check it."
  end

  def mapping_lines
    TestMapping.text.lines(chomp: true)
  end

  # The summary row of an AC.
  def row(id)
    mapping_lines.find { |line| line.start_with?("| [#{id}]") }
  end

  def totals_line
    mapping_lines.find { |line| line.start_with?("Totals: ") }
  end

  # The lines of the section "## <heading>", up to the blank line before the next section.
  def section(heading)
    TestMapping.text[/^## #{Regexp.escape(heading)}\n.*?(?=\n\n## |\n\z)/m].split("\n", -1)
  end

  it "AC-29 with no tests and no plans, the mapping lists every AC of requirements.md section 10 as Not covered" do
    write_requirements("AC-01" => "A user can sign in with Google", "AC-02" => "A user can sign in with GitHub")

    expect(mapping_lines).to eq([
      generated_line,
      "",
      "| AC | Acceptance criterion | Backend tests | Frontend tests | Manual validation |",
      "|---|---|---|---|---|",
      "| [AC-01](#ac-01) | A user can sign in with Google | 0 | 0 | Not covered |",
      "| [AC-02](#ac-02) | A user can sign in with GitHub | 0 | 0 | Not covered |",
      "",
      "Totals: 0 backend tests and 0 frontend tests; a test listed under two ACs counts once. " \
        "Of the 2 ACs, 0 have automated tests, 0 rely on manual validation alone, and 2 are not covered.",
      "",
      "The nine cases that requirements.md section 7 requires are mapped by hand in the README's " \
        "[Test coverage](../../README.md#test-coverage).",
      "",
      "## AC-01",
      "",
      "A user can sign in with Google",
      "",
      "Not covered.",
      "",
      "## AC-02",
      "",
      "A user can sign in with GitHub",
      "",
      "Not covered.",
      "",
      "## Tests with no known AC",
      "",
      "None."
    ])
    expect(TestMapping.text).to end_with("None.\n")
  end

  it "AC-29 a backend test is listed under the AC its name starts with and counted as a backend test" do
    write_requirements("AC-01" => "Sign in with Google", "AC-02" => "Sign in with GitHub")
    write_spec(
      "backend/spec/requests/sign_in_spec.rb",
      rspec_test("AC-01 signs in with Google"),
      rspec_test("AC-01 keeps the session", keyword: "specify", quote: "'"),
      rspec_test("AC-02 signs in with GitHub", keyword: "example", parens: true),
      rspec_test("AC-02 shows \\\"the name\\\" and a back\\\\slash", keyword: "scenario", parens: true)
    )
    write_spec(
      "backend/spec/models/user_spec.rb",
      rspec_test("AC-01 counts a focused test", keyword: "fit", quote: "'"),
      rspec_test("AC-01 counts another one", keyword: "fspecify")
    )

    expect(row("AC-01")).to eq("| [AC-01](#ac-01) | Sign in with Google | 4 | 0 | None |")
    expect(row("AC-02")).to eq("| [AC-02](#ac-02) | Sign in with GitHub | 2 | 0 | None |")
    expect(section("AC-01")).to eq([
      "## AC-01",
      "",
      "Sign in with Google",
      "",
      "Backend tests: 4. Frontend tests: 0. Manual validation: None.",
      "",
      "- [backend/spec/models/user_spec.rb](../../backend/spec/models/user_spec.rb)",
      "  - AC-01 counts a focused test",
      "  - AC-01 counts another one",
      "- [backend/spec/requests/sign_in_spec.rb](../../backend/spec/requests/sign_in_spec.rb)",
      "  - AC-01 signs in with Google",
      "  - AC-01 keeps the session"
    ])
    expect(section("AC-02")).to include(
      "  - AC-02 signs in with GitHub",
      "  - AC-02 shows \"the name\" and a back\\slash"
    )
    expect(totals_line).to start_with("Totals: 6 backend tests and 0 frontend tests;")
  end

  it "AC-29 a frontend test is listed under the AC its name starts with and counted as a frontend test" do
    write_requirements("AC-01" => "Sign in with Google", "AC-02" => "Sign in with GitHub")
    write_spec("backend/spec/requests/sign_in_spec.rb", rspec_test("AC-01 signs in with Google"))
    write_vitest(
      "frontend/src/App.test.tsx",
      vitest_test("AC-01 shows the sign-in screen"),
      vitest_test('AC-01 shows \"Loading…\" first', keyword: "test", quote: '"', tail: ", async () => {"),
      [ "  it(", "    'AC-02 has a name that begins on the next line',", "    async () => {" ],
      vitest_test("AC-01 counts a focused test", keyword: "it.only")
    )
    write_vitest(
      "frontend/src/lib/dates.spec.ts",
      vitest_test("AC-01 reads a template literal", quote: "`"),
      vitest_test("AC-01 counts a concurrent test", keyword: "test.concurrent")
    )
    write_vitest(
      "frontend/tools/build.test.mjs",
      vitest_test("AC-02 counts a sequential test", keyword: "it.sequential"),
      vitest_test("AC-02 counts a test that is expected to fail", keyword: "test.fails")
    )
    write_vitest("frontend/node_modules/some-lib/index.test.js", vitest_test("AC-02 is not a test of the app"))
    write_vitest("frontend/src/helpers.ts", vitest_test("AC-02 is not in a test file"))

    expect(row("AC-01")).to eq("| [AC-01](#ac-01) | Sign in with Google | 1 | 5 | None |")
    expect(row("AC-02")).to eq("| [AC-02](#ac-02) | Sign in with GitHub | 0 | 3 | None |")
    expect(section("AC-01")).to eq([
      "## AC-01",
      "",
      "Sign in with Google",
      "",
      "Backend tests: 1. Frontend tests: 5. Manual validation: None.",
      "",
      "- [backend/spec/requests/sign_in_spec.rb](../../backend/spec/requests/sign_in_spec.rb)",
      "  - AC-01 signs in with Google",
      "- [frontend/src/App.test.tsx](../../frontend/src/App.test.tsx)",
      "  - AC-01 shows the sign-in screen",
      "  - AC-01 shows \"Loading…\" first",
      "  - AC-01 counts a focused test",
      "- [frontend/src/lib/dates.spec.ts](../../frontend/src/lib/dates.spec.ts)",
      "  - AC-01 reads a template literal",
      "  - AC-01 counts a concurrent test"
    ])
    expect(section("AC-02")).to eq([
      "## AC-02",
      "",
      "Sign in with GitHub",
      "",
      "Backend tests: 0. Frontend tests: 3. Manual validation: None.",
      "",
      "- [frontend/src/App.test.tsx](../../frontend/src/App.test.tsx)",
      "  - AC-02 has a name that begins on the next line",
      "- [frontend/tools/build.test.mjs](../../frontend/tools/build.test.mjs)",
      "  - AC-02 counts a sequential test",
      "  - AC-02 counts a test that is expected to fail"
    ])
    expect(totals_line).to start_with("Totals: 1 backend tests and 8 frontend tests;")
  end

  it "AC-29 a group named with an AC ID is not a test" do
    write_requirements("AC-01" => "Sign in with Google")
    write_file(
      "backend/spec/requests/sign_in_spec.rb",
      'RSpec.describe "AC-01 sign-in" do',
      '  describe "AC-01 the callback" do',
      '    context("AC-01 with a new user") do',
      "      around do |example|",
      "        example.run",
      "      end",
      "",
      rspec_test("AC-01 creates the user"),
      "      end",
      "    end",
      "  end",
      "end"
    )
    write_file(
      "frontend/src/App.test.tsx",
      "describe('AC-01 the sign-in screen', () => {",
      "  describe('AC-01 its buttons', () => {",
      vitest_test("AC-01 shows both buttons"),
      "    })",
      "  })",
      "})"
    )

    expect(row("AC-01")).to eq("| [AC-01](#ac-01) | Sign in with Google | 1 | 1 | None |")
    expect(section("AC-01").grep(/^  - /)).to eq([ "  - AC-01 creates the user", "  - AC-01 shows both buttons" ])
    expect(section("Tests with no known AC")).to eq([ "## Tests with no known AC", "", "None." ])
    expect(totals_line).to start_with("Totals: 1 backend tests and 1 frontend tests;")
  end

  it "AC-29 a test whose name starts with two AC IDs is listed under both and counted once in the totals" do
    write_requirements("AC-13" => "Mark a note as reviewed", "AC-14" => "Recalculate the next review date")
    write_spec(
