    expect(row("AC-13")).to eq("| [AC-13](#ac-13) | Mark a note as reviewed | 2 | 1 | None |")
    expect(row("AC-14")).to eq("| [AC-14](#ac-14) | Recalculate the next review date | 1 | 1 | None |")
    expect(section("AC-13").grep(/^  - /)).to eq([
      "  - AC-13 AC-14 marks a note as reviewed and recalculates the next review date",
      "  - AC-13 marks a note as reviewed before AC-14 recalculates the date",
