    write_vitest("frontend/src/Probe.test.ts", vitest_test("AC-31 probe"), vitest_test("ac-01 has a lowercase AC ID"))

    probe = "- [backend/spec/models/probe_spec.rb](../../backend/spec/models/probe_spec.rb): "
