    expect(row("AC-01")).to eq("| [AC-01](#ac-01) | Sign in with Google | 1 | 0 | None |")
    expect(section("AC-01").grep(/^  - /)).to eq([ "  - AC-01 has a known AC ID" ])
    expect(row("AC-13")).to eq("| [AC-13](#ac-13) | Mark a note as reviewed | 0 | 0 | Not covered |")
    expect(section("AC-13")).to eq([ "## AC-13", "", "Mark a note as reviewed", "", "Not covered." ])
    expect(totals_line).to start_with("Totals: 7 backend tests and 2 frontend tests;")
