  it "AC-29 the manual validation shows the plan's Test plan items and how many passed by their last Result line" do
    write_requirements(
      "AC-01" => "Sign in with Google", "AC-02" => "Sign in with GitHub", "AC-03" => "Create the user",
      "AC-04" => "Keep the session", "AC-05" => "Log out", "AC-06" => "Collections"
    )
    write_spec("backend/spec/requests/sign_in_spec.rb", rspec_test("AC-01 signs in"), rspec_test("AC-03 creates the user"))
    write_plan(
      "01_google_sign_in",
      results: [
        [ "Pass, 2026-11-05. The button shows." ],
        [ "Fail, 2026-11-05. No message.", "Pass, 2026-11-06. After the fix, the message shows." ],
        [ "Pass, 2026-11-05.", "Fail, 2026-11-06. It broke again." ],
        [ "Waived by the owner, 2026-11-05." ],
        [ "Skipped, 2026-11-09, as the harness cannot reach Google." ],
        [ "not run" ],
        [ "Not a walkthrough item, 2026-11-09: a document scenario." ],
        []
      ],
      docs: [ true, false ]
    )
    write_plan("02_github_sign_in", results: Array.new(12) { [ "Pass, 2026-11-09, automated walkthrough." ] })
    write_plan("05_logout", results: [ [ "not run" ] ])
    write_plan("06_collections_crud")

    google = "[Test plan: 8 items, 2 passed](../features/01_google_sign_in/plan.md#test-plan)"
    github = "[Test plan: 12 items, 12 passed](../features/02_github_sign_in/plan.md#test-plan)"
    logout = "[Test plan: 1 item, 0 passed](../features/05_logout/plan.md#test-plan)"
    expect(row("AC-01")).to eq("| [AC-01](#ac-01) | Sign in with Google | 1 | 0 | #{google} |")
    expect(section("AC-01")[4]).to eq("Backend tests: 1. Frontend tests: 0. Manual validation: #{google}.")
    expect(row("AC-02")).to eq("| [AC-02](#ac-02) | Sign in with GitHub | 0 | 0 | #{github} |")
    expect(section("AC-02")).to eq([
      "## AC-02", "", "Sign in with GitHub", "", "Backend tests: 0. Frontend tests: 0. Manual validation: #{github}."
    ])
    expect(row("AC-03")).to eq("| [AC-03](#ac-03) | Create the user | 1 | 0 | None |")
    expect(section("AC-03")[4]).to eq("Backend tests: 1. Frontend tests: 0. Manual validation: None.")
    expect(row("AC-04")).to eq("| [AC-04](#ac-04) | Keep the session | 0 | 0 | Not covered |")
    expect(row("AC-05")).to eq("| [AC-05](#ac-05) | Log out | 0 | 0 | #{logout} |")
    expect(row("AC-06")).to eq("| [AC-06](#ac-06) | Collections | 0 | 0 | Not covered |")
    expect(section("AC-06")).to eq([ "## AC-06", "", "Collections", "", "Not covered." ])
  end

  it "AC-29 an AC whose result is a document also shows its plan's Docs checks and how many are ticked" do
    write_requirements(
      "AC-06" => "Collections", "AC-07" => "Collection deletion is documented", "AC-26" => "Runs locally",
      "AC-28" => "Specification artifacts", "AC-29" => "Test mapping", "AC-30" => "README"
    )
    write_plan("06_collections_crud", results: [ [ "Pass, 2026-11-09." ] ], docs: [ true, true ])
    write_plan("07_collection_delete_rule", results: [ [ "Pass, 2026-11-09." ] ], docs: [ true, true, false ])
    write_plan("26_local_run", docs: [ true ])
    write_plan("28_spec_artifacts", results: [ [ "Pass, 2026-11-09." ], [ "not run" ] ])
    write_plan("29_test_mapping", results: Array.new(14) { [ "Pass, 2026-11-09." ] }, docs: Array.new(6) { true })

    plan = ->(folder) { "../features/#{folder}/plan.md" }
    expect(row("AC-06")).to end_with(
      "| [Test plan: 1 item, 1 passed](#{plan["06_collections_crud"]}#test-plan) |"
    )
    expect(row("AC-07")).to end_with(
      "| [Test plan: 1 item, 1 passed](#{plan["07_collection_delete_rule"]}#test-plan); " \
        "[Docs checks: 3, 2 ticked](#{plan["07_collection_delete_rule"]}#docs) |"
    )
    expect(row("AC-26")).to eq(
      "| [AC-26](#ac-26) | Runs locally | 0 | 0 | [Docs checks: 1, 1 ticked](#{plan["26_local_run"]}#docs) |"
    )
    expect(row("AC-28")).to end_with("| [Test plan: 2 items, 1 passed](#{plan["28_spec_artifacts"]}#test-plan) |")
    expect(section("AC-29")[4]).to eq(
      "Backend tests: 0. Frontend tests: 0. Manual validation: " \
        "[Test plan: 14 items, 14 passed](#{plan["29_test_mapping"]}#test-plan); " \
        "[Docs checks: 6, 6 ticked](#{plan["29_test_mapping"]}#docs)."
    )
    expect(row("AC-30")).to end_with("| Not covered |")
  end

  it "AC-29 the totals count the ACs with automated tests, with manual validation alone, and not covered" do
    write_requirements(
      "AC-01" => "Sign in with Google", "AC-02" => "Sign in with GitHub", "AC-03" => "Create the user",
      "AC-04" => "Keep the session", "AC-05" => "Log out", "AC-06" => "Collections"
    )
    write_spec(
      "backend/spec/requests/sign_in_spec.rb",
      rspec_test("AC-01 signs in with Google"),
      rspec_test("AC-01 AC-02 signs in with either provider"),
      rspec_test("AC-04 keeps the session", keyword: "xit"),
      rspec_test("AC-99 has no known AC")
    )
    write_vitest(
      "frontend/src/App.test.tsx",
      vitest_test("AC-02 shows the GitHub button"),
      vitest_test("AC-02 shows the name"),
      vitest_test("AC-05 logs out", keyword: "it.skip")
    )
    write_plan("02_github_sign_in", results: [ [ "Pass, 2026-11-09." ] ])
    write_plan("03_user_auto_create", results: [ [ "not run" ] ])
    write_plan("04_session_persistence", results: [ [ "Pass, 2026-11-09." ] ])
    write_plan("06_collections_crud")

    expect(totals_line).to eq(
      "Totals: 3 backend tests and 2 frontend tests; a test listed under two ACs counts once. " \
        "Of the 6 ACs, 2 have automated tests, 2 rely on manual validation alone, and 2 are not covered."
    )
